import {RETAIL_PLAYMATS} from './retail-playmats.js';
// Device-local appearance only. No game, deck, account or network state is stored here.
export const PLAYMAT_DB='duema.playmat.v1';
export const PLAYMAT_PRESETS=[['standard','標準'],['forest','深緑の紋章'],['ocean','蒼の波紋'],['ember','紅の炎紋'],...RETAIL_PLAYMATS.map(p=>[p.id,p.name])];
const clamp=(v,min,max,fallback)=>Number.isFinite(Number(v))?Math.min(max,Math.max(min,Number(v))):fallback;
const imageOK=b=>b instanceof Blob&&['image/jpeg','image/png','image/webp'].includes(b.type)&&b.size>0&&b.size<=2*1024*1024;
export function normalizePlaymat(v){return {preset:[...PLAYMAT_PRESETS.map(p=>p[0]),'custom'].includes(v?.preset)?v.preset:'standard',brightness:clamp(v?.brightness??65,30,90,65),scale:clamp(v?.scale??100,100,180,100),x:clamp(v?.x??50,0,100,50),y:clamp(v?.y??50,0,100,50),image:imageOK(v?.image)?v.image:null};}
export function createPlaymatStore(idb=globalThis.indexedDB){
 async function open(){if(!idb)throw Error('このブラウザでは設定を保存できません。');return new Promise((resolve,reject)=>{const r=idb.open(PLAYMAT_DB,1);let blocked=false;r.onupgradeneeded=()=>r.result.createObjectStore('settings');r.onerror=()=>reject(Error('プレイマットの保存領域を開けませんでした。'));r.onblocked=()=>{blocked=true;reject(Error('別のタブを閉じて、もう一度お試しください。'));};r.onsuccess=()=>{if(blocked)r.result.close();else resolve(r.result);};});}
 async function transact(mode,value){const db=await open();try{return await new Promise((resolve,reject)=>{const t=db.transaction('settings',mode),store=t.objectStore('settings'),r=mode==='readwrite'?store.put(value,'current'):store.get('current');let result;r.onsuccess=()=>{result=r.result;};t.oncomplete=()=>resolve(result);t.onabort=t.onerror=()=>reject(Error('設定を保存できませんでした。空き容量やブラウザの設定をご確認ください。'));});}finally{db.close();}}
 return {read:()=>transact('readonly'),write:v=>transact('readwrite',v)};
}
// Decode and resize locally so a large phone photo never fills deck storage.
export async function preparePlaymatImage(file,{doc=globalThis.document,url=globalThis.URL,ImageClass=globalThis.Image}={}){
 if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('JPEG・PNG・WebPの画像を選んでください。');
 if(file.size>8*1024*1024)throw Error('画像は8MB以下にしてください。');
 const src=url.createObjectURL(file),img=new ImageClass();
 try{await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('画像を読み込めませんでした。別の画像をお試しください。'));img.src=src;});if(!img.naturalWidth||!img.naturalHeight||img.naturalWidth*img.naturalHeight>32_000_000)throw Error('画像が大きすぎます。小さくしてから選び直してください。');const ratio=Math.min(1,2048/Math.max(img.naturalWidth,img.naturalHeight)),canvas=doc.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*ratio));canvas.height=Math.max(1,Math.round(img.naturalHeight*ratio));const ctx=canvas.getContext('2d');if(!ctx)throw Error('画像を準備できませんでした。');ctx.fillStyle='#0b1718';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.85));if(!imageOK(blob))throw Error('画像を保存サイズに収められませんでした。小さい画像を選んでください。');return blob;}finally{url.revokeObjectURL(src);}
}
export function createPlaymatController({doc=globalThis.document,store=createPlaymatStore(),url=globalThis.URL,prepareImage=preparePlaymatImage}={}){
 let state={...normalizePlaymat(),opponent:normalizePlaymat()},queue=Promise.resolve(),initialError='';
 const imageURLs={own:{image:null,url:null},opponent:{image:null,url:null}};
 function apply(value=state,previewSide=null){const root=doc.documentElement,configs={own:normalizePlaymat(previewSide==='opponent'?state:value),opponent:normalizePlaymat(previewSide==='opponent'?value:value.opponent??state.opponent)};
  if(previewSide==='own')configs.opponent=normalizePlaymat(state.opponent);
  for(const [side,p]of Object.entries(configs)){const cache=imageURLs[side],retail=RETAIL_PLAYMATS.find(r=>r.id===p.preset);if(cache.image!==p.image){if(cache.url)url.revokeObjectURL(cache.url);cache.url=p.image?url.createObjectURL(p.image):null;cache.image=p.image;}
   root.setAttribute(side==='own'?'data-playmat':'data-opponent-playmat',p.preset==='custom'&&!cache.url?'standard':p.preset);
   const values={'image':cache.url?'url("'+cache.url+'")':'none','retail-image':retail?'url("'+retail.local+'")':'none','shade':String(1-p.brightness/100),'scale':String(p.scale/100),'x':p.x+'%','y':p.y+'%'};
   for(const [key,value]of Object.entries(values)){root.style.setProperty('--'+side+'-playmat-'+key,value);if(side==='own')root.style.setProperty('--playmat-'+key,value);}
  }
 }
 apply();const ready=Promise.resolve().then(()=>store.read()).then(v=>{state={...normalizePlaymat(v),opponent:normalizePlaymat(v?.opponent??v)};apply();}).catch(e=>{initialError=e.message;});
 // Keep the original top-level fields for own settings; the other side is an optional additive record.
 function save(patch,side='own'){const job=queue.catch(()=>{}).then(async()=>{await ready;const config=normalizePlaymat({...snapshot(side),...patch});if(config.preset==='custom'&&!config.image)throw Error('先に画像を選んでください。');const next=side==='opponent'?{...state,opponent:config}:{...config,opponent:state.opponent};await store.write(next);state=next;apply();return snapshot(side);});queue=job;return job;}
 function snapshot(side='own'){return {...normalizePlaymat(side==='opponent'?state.opponent:state)};}
 function html(){return `<div class="playmat-settings" data-playmat-settings><p class="small">自分の画面だけに適用します。画像と設定はこのブラウザに保存し、対戦相手には送りません。</p><div class="playmat-side-switch" role="group" aria-label="変更する側"><button type="button" data-playmat-side="own" aria-pressed="true">自分の場</button><button type="button" data-playmat-side="opponent" aria-pressed="false">相手の場 · 反対向き</button></div><div class="playmat-preview" data-playmat-preview="own" aria-label="プレイマットのプレビュー"><span>プレイマット</span><b aria-hidden="true">DUEL MASTERS</b><span data-playmat-preview-owner>自分側</span><i aria-hidden="true"></i></div><fieldset class="playmat-presets"><legend>プレイマットを選ぶ</legend>${PLAYMAT_PRESETS.filter(([id])=>!id.startsWith('retail-')).map(([id,label])=>`<button type="button" data-playmat-preset="${id}" aria-pressed="false"><span class="playmat-swatch" data-mat="${id}" aria-hidden="true"></span>${label}</button>`).join('')}<button type="button" data-playmat-preset="custom" aria-pressed="false"><span class="playmat-swatch" data-mat="custom" aria-hidden="true"></span>持ち込み画像</button></fieldset><fieldset class="playmat-presets playmat-retail"><legend>市販ラバーマットの柄</legend>${RETAIL_PLAYMATS.map(r=>`<button type="button" data-playmat-preset="${r.id}" aria-pressed="false"><img src="${r.local}" alt="" loading="lazy" decoding="async" width="1000" height="584"><span>${r.name}</span></button>`).join('')}</fieldset><p class="playmat-product small" data-playmat-product hidden><strong data-playmat-product-name></strong><a data-playmat-product-link target="_blank" rel="noopener noreferrer">公式の商品情報 ↗</a></p><label class="playmat-upload">画像を選ぶ<input type="file" accept="image/jpeg,image/png,image/webp" data-playmat-file><small>JPEG・PNG・WebP、8MBまで。自分側・相手側に各1枚保存できます。</small></label><div class="playmat-adjustments">${[['brightness','画像の明るさ',30,90,'%'],['scale','拡大率',100,180,'%'],['x','左右の位置',0,100,'%'],['y','上下の位置',0,100,'%']].map(([key,label,min,max,unit])=>`<label>${label}<output data-playmat-output="${key}"></output><input type="range" min="${min}" max="${max}" step="1" data-playmat-control="${key}" aria-label="${label}" data-unit="${unit}"></label>`).join('')}</div><div class="playmat-tools"><button type="button" class="btn" data-playmat-reset>位置・明るさを戻す</button><button type="button" class="btn" data-playmat-remove>保存した画像を削除</button></div><p class="notice" role="status" aria-live="polite" data-playmat-status>設定を読み込み中…</p></div>`;}
 async function mount(container){await ready;if(!container?.isConnected)return;let busy=false,side='own';
  const status=text=>{container.querySelector('[data-playmat-status]').textContent=text;};
  function sync(){const p=snapshot(side);container.style?.setProperty('--playmat-image','var(--'+side+'-playmat-image)');for(const el of container.querySelectorAll('[data-playmat-side]')){el.setAttribute('aria-pressed',String(el.dataset.playmatSide===side));el.disabled=busy;}container.querySelector('[data-playmat-preview]')?.setAttribute?.('data-playmat-preview',side);container.querySelector('[data-playmat-preview-owner]').textContent=side==='own'?'自分側':'相手側 · 180度回転';const retail=RETAIL_PLAYMATS.find(r=>r.id===p.preset),product=container.querySelector('[data-playmat-product]');product.hidden=!retail;if(retail){container.querySelector('[data-playmat-product-name]').textContent=(side==='own'?'自分側：':'相手側：')+retail.name;container.querySelector('[data-playmat-product-link]').href=retail.source;}for(const el of container.querySelectorAll('[data-playmat-preset]')){el.setAttribute('aria-pressed',String(el.dataset.playmatPreset===p.preset));el.disabled=busy||el.dataset.playmatPreset==='custom'&&!p.image;}for(const el of container.querySelectorAll('[data-playmat-control]')){el.value=p[el.dataset.playmatControl];el.disabled=busy||p.preset==='standard'||['scale','x','y'].includes(el.dataset.playmatControl)&&p.preset!=='custom'&&!p.preset.startsWith('retail-');container.querySelector(`[data-playmat-output="${el.dataset.playmatControl}"]`).textContent=el.value+'%';}container.querySelector('[data-playmat-file]').disabled=busy;container.querySelector('[data-playmat-remove]').disabled=busy||!p.image;container.querySelector('[data-playmat-reset]').disabled=busy;}
  async function commit(fn){busy=true;sync();status('保存しています…');try{await fn();status('このブラウザに保存しました。');}catch(e){apply();status(e.message||'設定を保存できませんでした。');}finally{busy=false;if(container.isConnected)sync();}}
  sync();status(initialError||'変更は自動で保存されます。');
  container.addEventListener('click',event=>{if(busy)return;const el=event.target.closest('button');if(!el)return;if(el.dataset.playmatSide){side=el.dataset.playmatSide;sync();status('選んだ側の設定を変更します。');return;}if(el.dataset.playmatPreset)commit(()=>save({preset:el.dataset.playmatPreset},side));else if(el.hasAttribute('data-playmat-reset'))commit(()=>save({brightness:65,scale:100,x:50,y:50},side));else if(el.hasAttribute('data-playmat-remove'))commit(()=>save({image:null,...(snapshot(side).preset==='custom'?{preset:'standard'}:{})},side));});
  container.addEventListener('input',event=>{const el=event.target,key=el.dataset.playmatControl;if(busy||!key)return;apply({...snapshot(side),[key]:Number(el.value)},side);container.querySelector(`[data-playmat-output="${key}"]`).textContent=el.value+'%';});
  container.addEventListener('change',event=>{if(busy)return;const el=event.target,key=el.dataset.playmatControl;if(key){const value=Number(el.value);commit(()=>save({[key]:value},side));}if(el.hasAttribute('data-playmat-file')){const file=el.files?.[0];el.value='';if(file)commit(async()=>{const image=await prepareImage(file);await save({image,preset:'custom',scale:100,x:50,y:50},side);});}});
 }
 return {ready,snapshot,save,apply,html,mount};
}
